/** Cultural identity survives changes of ruler and occupation. */
export const REGIONAL_CULTURES = [
 {id:'rainward',culture:'Marcher Households',government:'Hereditary March',regime:'crown',title:'Margrave',court:'March Court',succession:'A member of the ruling household inherits, subject to the assent of the border lords.',custom:'A guest is offered dry clothes and soup before being asked their business.',tradition:'At Floodwake, households repair the levees together and read the names of those lost to the river.',festivalDay:32,festival:'Floodwake',economy:'Bog iron, levee building and grain farming',tension:'The March maintains the border watches but expects its neighbors to pay for protected crossings.',history:'The first marcher charter exchanged military service for farmland above the flood line. Tenant households still petition the court over the number of days owed.',values:'Hospitality, household duty and a witnessed oath',diplomacy:'A witnessed border survey and a shared crossing charter',anchors:[.25,.32]},
 {id:'saltreach',culture:'Saltward Port Communities',government:'League of Free Cities',regime:'council',title:'First Speaker',court:'Assembly of Harbors',succession:'Port delegates elect a First Speaker for a six-year term; no household owns the office.',custom:'Visitors announce their name at the shared table; a ship’s crew eats before its captain.',tradition:'On Lanterns Afloat, small boats carry lights for missing sailors. Harbor debts are read publicly the next morning.',festivalDay:173,festival:'Lanterns Afloat',economy:'Shipping, salt pans, fisheries and foreign cloth',tension:'The ports demand open roads, while inland rulers demand tolls on the grain the ports need.',history:'Three harbors bought their independence after a king failed to repair their storm walls. Smaller ports now contest the voting weight of the richest merchants.',values:'Public accounts, free passage and crew solidarity',diplomacy:'Reciprocal toll limits and protected grain shipments',anchors:[.8,.35]},
 {id:'highstone',culture:'Highstone Hall Clans',government:'Confederation of Clans',regime:'council',title:'High Warden',court:'Moot of Halls',succession:'Hall delegates choose a High Warden. A failed confidence vote or an eight-year term returns the choice to the moot.',custom:'Tools are returned sharpened; anyone may shelter in a marked winter house.',tradition:'At First Thaw, each hall opens its winter stores and settles unpaid repair work before the passes reopen.',festivalDay:71,festival:'First Thaw',economy:'Ore, masonry, metalwork and mountain caravans',tension:'Mine boundaries and the right to use winter passes bring neighboring halls into dispute.',history:'Independent mining halls built the pass road jointly. The compact gives each hall a voice, but ownership of newly uncovered ore remains unsettled.',values:'Craft, mutual shelter and obligations recorded in stone',diplomacy:'A joint mine survey and a winter-road guarantee',anchors:[.48,.15]},
 {id:'blackgrove',culture:'Vale Grove Communities',government:'Covenant of Groves',regime:'order',title:'Grove Speaker',court:'Root Council',succession:'Village delegates select a speaker for seven years. Grove keepers witness the vote and may not hold the office.',custom:'Ask before taking living wood; fallen branches may be gathered for a traveler’s fire.',tradition:'At Seedshare, every village trades seed and adopts responsibility for a stand of young trees.',festivalDay:108,festival:'Seedshare',economy:'Orchards, timber, remedies and forest guides',tension:'Shipyards and armies seek timber faster than the groves can replace it.',history:'After a timber famine, the villages agreed on common woodland limits. The oldest covenant reserves hunting and planting rights to resident households, including newcomers.',values:'Stewardship, village consent and seasonal work',diplomacy:'Enforceable timber quotas and repayment for cleared land',anchors:[.28,.75]},
 {id:'ashplain',culture:'Emberward Communities',government:'Elected Protectorate',regime:'order',title:'Protector',court:'Council of Wells',succession:'Well wards elect a Protector for five years. Commanders must relinquish military authority before standing.',custom:'Water is offered freely at a public cistern; wasting it is an insult to the whole ward.',tradition:'During Hearthmend, families rebuild one abandoned hearth and share a meal with the people who will use it.',festivalDay:263,festival:'Hearthmend',economy:'Glasswork, caravan escorts and irrigated farming',tension:'Cistern access and the cost of defending displaced households divide the border wards.',history:'The wards chose a common Protector after separate watch companies fought over wells. Their charter forbids hereditary command, though popular captains often try to keep power.',values:'Shared water, earned command and a refuge kept open',diplomacy:'A neutral water commission and civilian access to the wells',anchors:[.75,.73]},
 {id:'bellwater',culture:'Bellwater Ferry Commons',government:'River Republic',regime:'council',title:'Convenor',court:'Common Bench',succession:'Elected ferry and farming delegates choose a Convenor for four years; the public bench hears challenges.',custom:'A place is left at supper for an absent household member, and another for an unexpected guest.',tradition:'On Namesday, families read the names of their dead and repair a communal landing in their memory.',festivalDay:302,festival:'Namesday',economy:'River freight, pottery, grain and ferry building',tension:'Private toll claims threaten crossings that ferry households maintain in common.',history:'Ferry households pooled their boats during a flood and refused the toll lord’s return. Their descendants govern with farmers and potters, while river estates seek to recover old privileges.',values:'Remembered kin, common crossings and accountable office',diplomacy:'Public ferry rights and compensation for repaired landings',anchors:[.48,.48]},
];
export const regionalCulture=id=>REGIONAL_CULTURES.find(r=>r.id===id)||null;

/** Older saved governments keep their actual ruling style and succession. */
export function regionalGovernment(id,regime){const c=regionalCulture(id);if(!c)return null;if(!regime||regime===c.regime)return {government:c.government,title:c.title,succession:c.succession};return regime==='crown'?{government:'Hereditary Crown',title:'Sovereign',succession:'The court confirms an heir under the existing hereditary charter.'}:regime==='council'?{government:'Council Government',title:'First Delegate',succession:'Local delegates choose a leader for a six-year term under the existing council charter.'}:{government:'Sworn Order',title:'Warden',succession:'Representatives of the order confirm a warden for a five-year term under the existing charter.'};}
